/// Verifies that a buffer of bytes contains a `DAV`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_dav_unchecked`.
#[inline]
pub fn root_as_dav(buf: &[u8]) -> Result<DAV<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<DAV>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `DAV` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `size_prefixed_root_as_dav_unchecked`.
#[inline]
pub fn size_prefixed_root_as_dav(buf: &[u8]) -> Result<DAV<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<DAV>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `DAV` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_dav_unchecked`.
#[inline]
pub fn root_as_dav_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<DAV<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<DAV<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `DAV` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_dav_unchecked`.
#[inline]
pub fn size_prefixed_root_as_dav_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<DAV<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<DAV<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a DAV and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `DAV`.
#[inline]
pub unsafe fn root_as_dav_unchecked(buf: &[u8]) -> DAV<'_> {
    unsafe { ::flatbuffers::root_unchecked::<DAV>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed DAV and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `DAV`.
#[inline]
pub unsafe fn size_prefixed_root_as_dav_unchecked(buf: &[u8]) -> DAV<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<DAV>(buf) }
}

pub const DAV_IDENTIFIER: &str = "$DAV";

#[inline]
pub fn dav_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, DAV_IDENTIFIER, false)
}

#[inline]
pub fn dav_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, DAV_IDENTIFIER, true)
}

#[inline]
pub fn finish_dav_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<DAV<'a>>
) {
    fbb.finish(root, Some(DAV_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_dav_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<DAV<'a>>
) {
    fbb.finish_size_prefixed(root, Some(DAV_IDENTIFIER));
}
